if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b97890f2fdedbce0fbe843c2' and md5(to_jsonb(t)::text)='a26c31c80c8f22681047be197c43788e')then raise exception 'NATIVE_DEFINITION_CHANGED:official:equipment:es:b97890f2fdedbce0fbe843c2';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{rules,definition}',$native_444edd58c45ede93${"format":"equipment-definition-draft","schemaVersion":1,"id":"recovery:official:equipment:es:b97890f2fdedbce0fbe843c2","revision":1,"language":"es","name":"Talismán del mal definitivo","aliases":["Talismán Del Mal Definitivo"],"baseDefinitionId":null,"origin":"official","sources":[{"id":"original:b9bb410fc1dc7cca76c469ab345b983a829aa739eda2599bc5fe5b2c84255139","kind":"legacy","title":"Talismán Del Mal Definitivo","language":"es","rulesEdition":null,"locator":"official:equipment:es:b97890f2fdedbce0fbe843c2","verified":false},{"id":"original:a92f21d9cc5191c2ac40fd56751e881ebdaf640e5cf84fe108ee61c134438a14","kind":"legacy","title":"Talismán Del Mal Definitivo","language":"es","rulesEdition":null,"locator":"official:equipment:es:b97890f2fdedbce0fbe843c2","verified":false},{"id":"original:b693b1d8ee181089be318ede3437ad04f7ddfbead15be306688265dc0aa60466","kind":"legacy","title":"Talisman of Ultimate Evil","language":"en","rulesEdition":null,"locator":"official:equipment:eng:d0b13de91dab31fc3546a2e6","verified":false},{"id":"original:c1c9369ba7ea5282e953ca1b7f20d36d26a209cdeb551f890fe0e6942e59836d","kind":"legacy","title":"Talisman of Ultimate Evil","language":"en","rulesEdition":null,"locator":"official:equipment:eng:d0b13de91dab31fc3546a2e6","verified":false},{"id":"srd-5.1-es-equipment","kind":"srd","title":"Documento de referencia del sistema 5.1 · edición oficial española","language":"es","rulesEdition":"2014","locator":"https://media.wizards.com/2023/downloads/dnd/SRD_CC_v5.1_ES.pdf · página PDF 263 · CC BY 4.0","verified":true}],"category":"wondrous-item","subtypes":[],"magical":true,"rarity":"legendary","consumable":false,"properties":[],"weight":null,"economy":{"basePrice":null,"campaignPrice":null,"explanation":""},"description":[{"id":"official-rule-0","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Este objeto simboliza el mal impenitente. Una criatura cuyo alineamiento no sea ni bueno ni malvado sufrirá 6d6 de daño necrótico si lo toca. En cambio, si es de alineamiento bueno, sufrirá 8d6 de daño necrótico. En ambos casos, la criatura sufrirá el daño de nuevo cada vez que sostenga o lleve puesto el talismán al terminar su turno."},{"id":"official-rule-1","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Si eres un clérigo o paladín malvado, puedes usar el talismán como símbolo sagrado y obtienes un bonificador de +2 a las tiradas de ataque de conjuro mientras lo lleves puesto o lo sostengas."},{"id":"official-rule-2","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"El talismán tiene 6 cargas. Si lo llevas puesto o lo sostienes, puedes usar una acción para gastar 1 de sus cargas y elegir una criatura que puedas ver en el suelo a 36 m o menos de ti. Si el objetivo tiene alineamiento bueno, una grieta ardiente se abrirá bajo él. Deberá superar una tirada de salvación de Destreza con CD 20 o se caerá por la grieta y será destruido sin dejar ningún resto mortal. A continuación, la grieta se cerrará y no quedará ni huella de su existencia. Cuando gastes la última carga, el talismán se disolverá en un limo apestoso y se destruirá."}],"requirements":{"attunement":true,"bearer":[{"kind":"other","keys":[],"explanation":"Objeto maravilloso, legendario (requiere sintonización por parte de una criatura de alineamiento malvado)"}],"presence":"worn","explanation":"Objeto maravilloso, legendario (requiere sintonización por parte de una criatura de alineamiento malvado)"},"weapon":null,"armor":null,"resources":[],"capabilities":[{"id":"official-assisted-rule","name":"Reglas del objeto","activation":"other","trigger":"","requirements":{"attunement":true,"bearer":[{"kind":"other","keys":[],"explanation":"Objeto maravilloso, legendario (requiere sintonización por parte de una criatura de alineamiento malvado)"}],"presence":"worn","explanation":"Objeto maravilloso, legendario (requiere sintonización por parte de una criatura de alineamiento malvado)"},"target":"Según la regla oficial.","range":"","duration":"Según la regla oficial.","concentration":"spell-dependent","costs":[],"consumeQuantity":0,"effects":[{"id":"assisted-rule","condition":"","kind":"unmodeled","explanation":"Este objeto simboliza el mal impenitente. Una criatura cuyo alineamiento no sea ni bueno ni malvado sufrirá 6d6 de daño necrótico si lo toca. En cambio, si es de alineamiento bueno, sufrirá 8d6 de daño necrótico. En ambos casos, la criatura sufrirá el daño de nuevo cada vez que sostenga o lleve puesto el talismán al terminar su turno.\n\nSi eres un clérigo o paladín malvado, puedes usar el talismán como símbolo sagrado y obtienes un bonificador de +2 a las tiradas de ataque de conjuro mientras lo lleves puesto o lo sostengas.\n\nEl talismán tiene 6 cargas. Si lo llevas puesto o lo sostienes, puedes usar una acción para gastar 1 de sus cargas y elegir una criatura que puedas ver en el suelo a 36 m o menos de ti. Si el objetivo tiene alineamiento bueno, una grieta ardiente se abrirá bajo él. Deberá superar una tirada de salvación de Destreza con CD 20 o se caerá por la grieta y será destruido sin dejar ningún resto mortal. A continuación, la grieta se cerrará y no quedará ni huella de su existencia. Cuando gastes la última carga, el talismán se disolverá en un limo apestoso y se destruirá.","original":{"page":263,"source":"srd-5.1-es-equipment","metadata":"Objeto maravilloso, legendario (requiere sintonización por parte de una criatura de alineamiento malvado)"}}],"execution":{"mode":"assisted","handler":"equipment-text-assistance","explanation":"Consultar la regla oficial y resolver los efectos descritos en la mesa; no concede activaciones ni recuperaciones automáticas.","pendingAutomation":["Conectar los costes, objetivos, duración y efectos particulares de esta regla antes de habilitar su uso automático."]},"textBlockIds":["official-rule-0","official-rule-1","official-rule-2"]},{"id":"last-charge-check","name":"Última carga","activation":"trigger","trigger":"Al gastar la última carga del objeto.","requirements":{"attunement":true,"bearer":[{"kind":"other","keys":[],"explanation":"Objeto maravilloso, legendario (requiere sintonización por parte de una criatura de alineamiento malvado)"}],"presence":"worn","explanation":"Objeto maravilloso, legendario (requiere sintonización por parte de una criatura de alineamiento malvado)"},"target":"El objeto","range":"","duration":"Instantánea","concentration":false,"costs":[],"consumeQuantity":0,"effects":[{"id":"last-charge-outcome","kind":"last-charge-resolution","condition":"Después de gastar la última carga.","sides":null,"outcome":"destroy","replacementKey":null,"refillOnMaximum":null}],"execution":{"mode":"automatic","handler":"equipment-last-charge","explanation":"Aplica la consecuencia y, cuando corresponde, valida el d20 y la tirada de recuperación. Conserva la identidad del ejemplar y actualiza su forma, ataques y conjuros.","pendingAutomation":[]},"textBlockIds":["official-rule-2"]}],"recoverySourceIds":["b9bb410fc1dc7cca76c469ab345b983a829aa739eda2599bc5fe5b2c84255139","a92f21d9cc5191c2ac40fd56751e881ebdaf640e5cf84fe108ee61c134438a14","b693b1d8ee181089be318ede3437ad04f7ddfbead15be306688265dc0aa60466","c1c9369ba7ea5282e953ca1b7f20d36d26a209cdeb551f890fe0e6942e59836d"],"review":{"identity":true,"information":false,"editorial":true,"mechanics":false,"unresolved":["La descripción oficial española está recuperada íntegramente; faltan adaptar y validar las mecánicas particulares y cerrar la cobertura de todos los campos originales."]}}$native_444edd58c45ede93$::jsonb,true),'{features}',$native_8ee5d19ae1554acb$[{"id":"legacy-bonus-0","kind":"passive","name":"SpellAttackModifier","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Obtienes un bonificador de +2 a las tiradas de ataque de hechizos y a las CD de las tiradas de salvación de tus hechizos.","showInActions":false},{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este objeto simboliza el mal impenitente. Una criatura cuyo alineamiento no sea ni bueno ni malvado sufrirá 6d6 de daño necrótico si lo toca. En cambio, si es de alineamiento bueno, sufrirá 8d6 de daño necrótico. En ambos casos, la criatura sufrirá el daño de nuevo cada vez que sostenga o lleve puesto el talismán al terminar su turno.\n\nSi eres un clérigo o paladín malvado, puedes usar el talismán como símbolo sagrado y obtienes un bonificador de +2 a las tiradas de ataque de conjuro mientras lo lleves puesto o lo sostengas.\n\nEl talismán tiene 6 cargas. Si lo llevas puesto o lo sostienes, puedes usar una acción para gastar 1 de sus cargas y elegir una criatura que puedas ver en el suelo a 36 m o menos de ti. Si el objetivo tiene alineamiento bueno, una grieta ardiente se abrirá bajo él. Deberá superar una tirada de salvación de Destreza con CD 20 o se caerá por la grieta y será destruido sin dejar ningún resto mortal. A continuación, la grieta se cerrará y no quedará ni huella de su existencia. Cuando gastes la última carga, el talismán se disolverá en un limo apestoso y se destruirá.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$native_8ee5d19ae1554acb$::json