cial-block-1"]}],"recoverySourceIds":["1b049364611461329859d9013ada9edf8557420daf42cf8b784ce1dc90f59fd8","0111ef5a52f562c68dea4a6be9eb3d0fabc26e2f7d2897c1f60a0e945be7e770","d4b6f2c4f0303e1f24daf911b83ac8d9380967849be5fd12618917995bba246f","d8627d4873d4228b369dd010828a4f6cba6ac0afcc0bb4ee94609c852dd49832"],"review":{"identity":true,"information":false,"editorial":true,"mechanics":false,"unresolved":["Conservar originales y cerrar su recuperación antes de eliminar versiones."]}}$native_da85b4ec4723df39$::jsonb,true),'{features}',$native_cb1746b6035208e3$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este bastón se puede usar a modo de bastón mágico que otorga un bonificador de +3 a las tiradas de ataque y de daño realizadas con él.\n\nEl bastón tiene 10 cargas. Cuando impactes con un ataque cuerpo a cuerpo con él, podrás gastar hasta 3 cargas. Por cada carga empleada, el objetivo recibirá 1d6 de daño de fuerza adicional. El bastón recupera 1d6 + 4 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 1, el bastón se convierte en un bastón no mágico.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$native_cb1746b6035208e3$::jsonb,true),'{charges}',$native_45b436819bc8a817${"reset":"manual","current":10,"maximum":10}$native_45b436819bc8a817$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:cbfbeb4aafdeb42aa1660850';
